480:     private BufferPool internalCreateBufferPool(
481:             int numExpectedBuffers,
482:             int minUsedBuffers,
483:             int maxUsedBuffers,
484:             int numSubpartitions,
485:             int maxBuffersPerChannel,
486:             int maxOverdraftBuffersPerGate)
487:             throws IOException {
488: 
489:         // It is necessary to use a separate lock from the one used for buffer
490:         // requests to ensure deadlock freedom for failure cases.
491:         synchronized (factoryLock) {
492:             if (isDestroyed) {
493:                 throw new IllegalStateException("Network buffer pool has already been destroyed.");
494:             }
495: 
496:             // Ensure that the number of required buffers can be satisfied.
497:             // With dynamic memory management this should become obsolete.
498:             if (numTotalRequiredBuffers + minUsedBuffers > totalNumberOfMemorySegments) {
499:                 throw new IOException(
500:                         String.format(
501:                                 "Insufficient number of network buffers: "
502:                                         + "required %d, but only %d available. %s.",
503:                                 minUsedBuffers,
504:                                 totalNumberOfMemorySegments - numTotalRequiredBuffers,
505:                                 getConfigDescription()));
506:             }
507: 
508:             this.numTotalRequiredBuffers += minUsedBuffers;
509: 
510:             // We are good to go, create a new buffer pool and redistribute
511:             // non-fixed size buffers.
512:             LocalBufferPool localBufferPool =
513:                     new LocalBufferPool(
514:                             this,
515:                             numExpectedBuffers,
516:                             minUsedBuffers,
517:                             maxUsedBuffers,
518:                             numSubpartitions,
519:                             maxBuffersPerChannel,
520:                             maxOverdraftBuffersPerGate);
521: 
522:             allBufferPools.add(localBufferPool);
523: 
524:             if (minUsedBuffers < maxUsedBuffers) {
525:                 resizableBufferPools.add(localBufferPool);
526:             }
527: 
528:             redistributeBuffers();
529: 
530:             return localBufferPool;
531:         }
532:     }
