534:     @Override
535:     public void destroyBufferPool(BufferPool bufferPool) {
536:         if (!(bufferPool instanceof LocalBufferPool)) {
537:             throw new IllegalArgumentException("bufferPool is no LocalBufferPool");
538:         }
539: 
540:         synchronized (factoryLock) {
541:             if (allBufferPools.remove(bufferPool)) {
542:                 numTotalRequiredBuffers -= bufferPool.getMinNumberOfMemorySegments();
543:                 resizableBufferPools.remove(bufferPool);
544: 
545:                 redistributeBuffers();
546:             }
547:         }
548:     }
