550:     /**
551:      * Destroys all buffer pools that allocate their buffers from this buffer pool (created via
552:      * {@link #createBufferPool(int, int, int)}).
553:      */
554:     public void destroyAllBufferPools() {
555:         synchronized (factoryLock) {
556:             // create a copy to avoid concurrent modification exceptions
557:             LocalBufferPool[] poolsCopy =
558:                     allBufferPools.toArray(new LocalBufferPool[allBufferPools.size()]);
559: 
560:             for (LocalBufferPool pool : poolsCopy) {
561:                 pool.lazyDestroy();
562:             }
563: 
564:             // some sanity checks
565:             if (allBufferPools.size() > 0
566:                     || numTotalRequiredBuffers > 0
567:                     || resizableBufferPools.size() > 0) {
568:                 throw new IllegalStateException(
569:                         "NetworkBufferPool is not empty after destroying all LocalBufferPools");
570:             }
571:         }
572:     }
