574:     // Must be called from synchronized block
575:     private void tryRedistributeBuffers(int numberOfSegmentsToRequest) throws IOException {
576:         assert Thread.holdsLock(factoryLock);
577: 
578:         if (numTotalRequiredBuffers + numberOfSegmentsToRequest > totalNumberOfMemorySegments) {
579:             throw new IOException(
580:                     String.format(
581:                             "Insufficient number of network buffers: "
582:                                     + "required %d, but only %d available. %s.",
583:                             numberOfSegmentsToRequest,
584:                             totalNumberOfMemorySegments - numTotalRequiredBuffers,
585:                             getConfigDescription()));
586:         }
587: 
588:         this.numTotalRequiredBuffers += numberOfSegmentsToRequest;
589: 
590:         try {
591:             redistributeBuffers();
592:         } catch (Throwable t) {
593:             this.numTotalRequiredBuffers -= numberOfSegmentsToRequest;
594: 
595:             redistributeBuffers();
596:             ExceptionUtils.rethrow(t);
597:         }
598:     }
599: 
600:     // Must be called from synchronized block
601:     private void redistributeBuffers() {
602:         assert Thread.holdsLock(factoryLock);
603: 
604:         if (resizableBufferPools.isEmpty()) {
605:             return;
606:         }
607: 
608:         // All buffers, which are not among the required ones
609:         int numAvailableMemorySegment = totalNumberOfMemorySegments - numTotalRequiredBuffers;
610: 
611:         if (numAvailableMemorySegment == 0) {
612:             // in this case, we need to redistribute buffers so that every pool gets its minimum
613:             for (LocalBufferPool bufferPool : resizableBufferPools) {
614:                 bufferPool.setNumBuffers(bufferPool.getMinNumberOfMemorySegments());
615:             }
616:             return;
617:         }
618: 
619:         // Calculates the number of buffers that can be redistributed and the total weight of buffer
620:         // pools that are resizable
621:         int totalWeight = 0;
622:         int numBuffersToBeRedistributed = numAvailableMemorySegment;
623:         for (LocalBufferPool bufferPool : resizableBufferPools) {
624:             numBuffersToBeRedistributed += bufferPool.getMinNumberOfMemorySegments();
625:             totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
626:         }
627: 
628:         // First, all buffers are allocated proportionally according to the expected values of each
629:         // pool as weights. However, due to the constraints of minimum and maximum values, the
630:         // actual number of buffers distributed may be more or less than the total number of
631:         // buffers.
632:         int totalAllocated = 0;
633:         Map<LocalBufferPool, Integer> cachedPoolSize = new HashMap<>(resizableBufferPools.size());
634:         for (LocalBufferPool bufferPool : resizableBufferPools) {
635:             int expectedNumBuffers =
636:                     bufferPool.getExpectedNumberOfMemorySegments()
637:                             * numBuffersToBeRedistributed
638:                             / totalWeight;
639:             int actualAllocated =
640:                     Math.min(
641:                             bufferPool.getMaxNumberOfMemorySegments(),
642:                             Math.max(
643:                                     bufferPool.getMinNumberOfMemorySegments(), expectedNumBuffers));
644:             cachedPoolSize.put(bufferPool, actualAllocated);
645:             totalAllocated += actualAllocated;
646:         }
647: 
648:         // Now we need to deal with this difference, which may be greater than zero or less than
649:         // zero.
650:         int delta = numBuffersToBeRedistributed - totalAllocated;
651: 
652:         int remaining = Integer.MAX_VALUE;
653:         while (remaining != 0) {
654:             remaining = redistributeBuffers(delta, cachedPoolSize);
655: 
656:             // Stop the loop iteration when there is no remaining segments to be redistributed
657:             // or all local buffer pools have reached the max number.
658:             if (remaining == delta) {
659:                 break;
660:             }
661:             delta = remaining;
662:         }
663: 
664:         for (LocalBufferPool bufferPool : resizableBufferPools) {
665:             bufferPool.setNumBuffers(
666:                     cachedPoolSize.getOrDefault(
667:                             bufferPool, bufferPool.getMinNumberOfMemorySegments()));
668:         }
669:     }
670: 
671:     /**
672:      * @param delta the buffers to be redistributed.
673:      * @param cachedPoolSize the map to cache the intermediate result.
674:      * @return the remaining buffers that can continue to be redistributed.
675:      */
676:     private int redistributeBuffers(int delta, Map<LocalBufferPool, Integer> cachedPoolSize) {
677:         Set<LocalBufferPool> poolsToBeRedistributed = new HashSet<>();
678: 
679:         if (delta > 0) {
680:             // In this case, we need to allocate the remaining buffers to pools that have
681:             // not yet reached their maximum number.
682: 
683:             int totalWeight = 0;
684:             for (LocalBufferPool bufferPool : resizableBufferPools) {
685:                 if (cachedPoolSize.get(bufferPool) < bufferPool.getMaxNumberOfMemorySegments()) {
686:                     poolsToBeRedistributed.add(bufferPool);
687:                     totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
688:                 }
689:             }
690: 
691:             int totalAllocated = 0;
692:             float pieceOfDelta = ((float) delta) / totalWeight;
693:             for (LocalBufferPool bufferPool : poolsToBeRedistributed) {
694:                 int extraAllocated =
695:                         Math.min(
696:                                 delta - totalAllocated,
697:                                 (int)
698:                                         Math.ceil(
699:                                                 pieceOfDelta
700:                                                         * bufferPool
701:                                                                 .getExpectedNumberOfMemorySegments()));
702:                 int numBuffers =
703:                         Math.min(
704:                                 bufferPool.getMaxNumberOfMemorySegments(),
705:                                 cachedPoolSize.get(bufferPool) + extraAllocated);
706:                 totalAllocated += numBuffers - cachedPoolSize.get(bufferPool);
707:                 cachedPoolSize.put(bufferPool, numBuffers);
708:                 if (totalAllocated == delta) {
709:                     break;
710:                 }
711:             }
712:             return delta - totalAllocated;
713:         } else if (delta < 0) {
714:             // In this case, we need to take back the previously allocated buffers from pools that
715:             // have not yet reached their minimum number.
716: 
717:             int totalWeight = 0;
718:             for (LocalBufferPool bufferPool : resizableBufferPools) {
719:                 if (cachedPoolSize.get(bufferPool) == bufferPool.getMinNumberOfMemorySegments()) {
720:                     continue;
721:                 }
722:                 poolsToBeRedistributed.add(bufferPool);
723:                 totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
724:             }
725: 
726:             int totalDeallocated = 0;
727:             int deltaAbs = Math.abs(delta);
728:             float pieceOfDelta = ((float) deltaAbs) / totalWeight;
729:             for (LocalBufferPool bufferPool : poolsToBeRedistributed) {
730:                 int extraDeallocated =
731:                         Math.min(
732:                                 deltaAbs - totalDeallocated,
733:                                 (int)
734:                                         Math.ceil(
735:                                                 pieceOfDelta
736:                                                         * bufferPool
737:                                                                 .getExpectedNumberOfMemorySegments()));
738:                 int numBuffers =
739:                         Math.max(
740:                                 bufferPool.getMinNumberOfMemorySegments(),
741:                                 cachedPoolSize.get(bufferPool) - extraDeallocated);
742:                 totalDeallocated += cachedPoolSize.get(bufferPool) - numBuffers;
743:                 cachedPoolSize.put(bufferPool, numBuffers);
744:                 if (totalDeallocated == deltaAbs) {
745:                     break;
746:                 }
747:             }
748:             return delta + totalDeallocated;
749:         } else {
750:             return 0;
751:         }
752:     }
